await write('08_LOCALIZATION/FIELD_LOCALIZATION_EN.txt',`The live website resolves display values from PostgreSQL, not from these JSON files. Files here are seed/import sources.\n\nCanonical tables: content_fields, field_translations. Locale definitions: locales. Page layout: page_definitions, page_positions, field_placements, localized_positions.\n\nExample field: material.abs-fiberlogy.description. Source English value and version are stored once. Each other locale has a separate row referencing that field and source version. Changing the source preserves a revision, makes existing translations stale and queues all registered locales. Current English is the temporary fallback; stale translations are not published. Moving a field changes every locale view without retranslating its value.\n\nInitial UI strings have English source values and draft translations in six languages. The technical catalog is authored in English; its translations are pending professional review. A new locale can be registered without code changes. The trigger queues missing translations automatically. All headings, labels, placeholders, errors, emails, alt text and metadata must follow the same canonical model in the completed application.\n`);
await write('10_AUTH_AND_ORDER/IMPLEMENTATION_REQUIREMENTS_EN.txt',`Google: https://developers.google.com/identity/gsi/web/guides/overview\nToken verification: https://developers.google.com/identity/gsi/web/guides/verify-google-id-token\nEU identity information: https://trusted-digital-identity.europa.eu/\n\nEU Pass has not been identified. Do not assume commercial EU Login integration is available. The adapter remains disabled pending provider confirmation and onboarding. Real Google credentials and configured callback URLs are also required before enabling sign-in.\n\nThe order form is specified in the master prompt and seeded in form_definitions/form_fields. Uploaded binary data belongs to PostgreSQL chunks. No public directory, shared cache or default third-party document processor may serve client originals. Customers can submit drafts and requests; engineer actions control feasibility, issued quotations and production states. The application must enforce roles in addition to database RLS; a customer must not self-promote a project to accepted/printing or edit quotation amounts.\n`);
const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EVA PRINT — Research package viewer</title><style>body{font:16px/1.6 system-ui;margin:0;background:#f5f8fb;color:#183247}header{background:#153648;color:white;padding:35px max(25px,calc((100vw - 1200px)/2))}main{max-width:1200px;margin:30px auto;padding:20px}h1{line-height:1.15}input{font:inherit;width:95%;padding:14px;border:1px solid #b2c9d4;border-radius:8px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:20px}article{background:white;border:1px solid #dce5ed;border-radius:12px;padding:20px}img{width:100%;height:auto;border-radius:6px}a{color:#087c8b}.note{background:#e5eef3;padding:20px;border-radius:8px}.tag{font-size:12px;background:#edf3f7;padding:4px 8px;border-radius:5px}details{margin:12px 0}button{font:inherit;padding:10px}</style><header><p>EVA PRINT SRL · Engineering research library</p><h1>Materials, industries<br>and technical references</h1><p>${counts.material_grades} supplier grades · ${counts.industries} industries · ${counts.documented_external_cases} documented external references</p></header><main><p class="note">This is an offline research viewer, not the deployed website. The implementation prompt specifies a Go application with database-defined fields, translations and layout. Reference photos are private research copies. Concept drawings are original illustrations; they are not manufacturing releases.</p><p><a href="../01_PROMPT/EVA_PRINT_MASTER_PROMPT_EN.txt">Full English website prompt</a> · <a href="../01_PROMPT/EVA_PRINT_MASTER_PROMPT_EN.pdf">Prompt PDF</a> · <a href="../07_DATABASE/schema.sql">PostgreSQL schema</a> · <a href="../07_DATABASE/002_dynamic_fields.sql">Dynamic fields and layout</a></p><label for="search">Search material, supplier or family</label><input id="search" placeholder="ABS, carbon fiber, Prusament…"><h2>Materials A–Z</h2><div class="cards">${materials.map(m=>`<article data-search="${esc((m.name+' '+m.family+' '+m.description_en).toLowerCase())}"><span class="tag">${esc(m.family)}</span><h3>${esc(m.name)}</h3><img loading="lazy" src="../${m.drawings.png}" alt="Original conceptual drawing for ${esc(m.name)}"><p>${esc(m.description_en)}</p><p><b>Advantages:</b> ${esc(m.advantages.join('; '))}</p><details><summary>Limitations, applications and technical documents</summary><p>${esc(m.limitations.join('; '))}</p><p>${m.application_examples.map(x=>esc(x.title)).join(' · ')}</p><p>Service: ${esc(m.service_status)}</p><ul>${m.datasheets.map(d=>`<li><a href="../${esc(d.path)}">${esc(d.document_type)} — local document</a> · <a href="${esc(d.url)}">Manufacturer link</a></li>`).join('')}</ul>${m.manufacturer_tds_status!=='downloaded'?'<p>Exact manufacturer TDS PDF was not retrieved; the company overview is labelled separately.</p>':''}<p><a href="../${m.engineering_overview}">EVA PRINT overview PDF</a> · <a href="../${m.drawings.pdf}">Drawing PDF</a> · <a href="../${m.drawings.dxf}">DXF</a></p><p><a href="${esc(m.source_url)}">Supplier source</a></p>${m.reference_photos.slice(0,2).map(x=>`<a href="../${esc(x.path)}">Private supplier reference photo</a> · `).join('')}</details></article>`).join('')}</div><h2>Industry applications</h2><div class="cards">${industries.map(i=>`<article><h3>${esc(i.name)}</h3><p>${esc(i.description_en)}</p><ul>${i.application_examples.map(x=>`<li>${esc(x.title)}</li>`).join('')}</ul><a href="../03_INDUSTRIES/${i.id}/description.en.txt">English industry description</a></article>`).join('')}</div><h2>Documented external inspiration</h2><div class="cards">${cases.map(c=>`<article><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><p>${esc(c.material)}</p><a href="${esc(c.source)}">Original case source</a>${c.photos?.length?` · <a href="../${esc(c.photos[0].path)}">Private reference photo</a>`:''}</article>`).join('')}</div></main><script>document.getElementById('search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q))});</script></html>`;
await write('11_PREVIEW/index.html',html);
console.log(JSON.stringify(counts,null,2));
